// Pure offline tests. All repository names, commit selectors and content are
// synthetic public fixtures; nothing here is an actual Source/Owner proof.
import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {createImmutableWorkflowSourceReader,PUBLISHER_SNAPSHOT_QUERY} from './clued-gated-proof-runtime.mjs';
assert.equal(typeof createImmutableWorkflowSourceReader,'function','candidate exposes the pure reader factory');

const repository='public-fixture/example';
const otherRepository='public-fixture/other';
const commitA='a'.repeat(40),commitB='b'.repeat(40);
const fileA='.github/workflows/public-one.yml';
const fileB='.github/workflows/public-two.yml';
const route=(file=fileA,commit=commitA,repo=repository)=>`/repos/${repo}/contents/${file}?ref=${commit}`;
const blob=bytes=>createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex');
function content(file=fileA,text='name: public fixture\non: workflow_dispatch\n') {
  const bytes=Buffer.from(text,'utf8');
  return {type:'file',path:file,sha:blob(bytes),encoding:'base64',content:bytes.toString('base64'),size:bytes.length,
    publicMetadata:{label:'provider original',values:['first']}};
}
function countedRead(produce=()=>content()) {
  const calls=[];
  const read=async(...args)=>{calls.push(args);return produce(args[0],calls.length);};
  return {calls,read};
}
const reader=(read,enabled=true,repo=repository)=>createImmutableWorkflowSourceReader({read,repository:repo,enabled});

test('valid immutable raw content is fetched once and reused exactly',async()=>{
  const expected=content(),source=countedRead(()=>expected),read=reader(source.read);
  const first=await read(route()),second=await read(route()),third=await read(route());
  assert.equal(source.calls.length,1);
  assert.deepEqual(first,expected);assert.deepEqual(second,expected);assert.deepEqual(third,expected);
  assert.notStrictEqual(second,first);assert.notStrictEqual(third,second);
});

test('complete UTF-8 with multibyte and CRLF content is reusable',async()=>{
  const expected=content(fileA,'name: 公开样本 😀\r\non: workflow_dispatch\r\n');
  const source=countedRead(()=>expected),read=reader(source.read);
  assert.deepEqual(await read(route()),expected);
  assert.deepEqual(await read(route()),expected);
  assert.equal(source.calls.length,1);
});

test('content at exactly the 524288-byte bound is reusable',async()=>{
  const expected=content(fileA,'x'.repeat(524288));
  const source=countedRead(()=>expected),read=reader(source.read);
  await read(route());await read(route());
  assert.equal(source.calls.length,1);
});

test('cache keys separate full commit SHA and safe path',async()=>{
  const source=countedRead(api=>content(api.includes(fileB)?fileB:fileA)),read=reader(source.read);
  const routes=[route(fileA,commitA),route(fileA,commitB),route(fileB,commitA),route(fileB,commitB)];
  for(const api of routes)await read(api);
  for(const api of routes)await read(api);
  assert.equal(source.calls.length,4);
  assert.deepEqual(source.calls.map(args=>args[0]),routes);
});

test('other repository never reuses configured repository content',async()=>{
  const source=countedRead(()=>content()),read=reader(source.read);
  await read(route());await read(route(fileA,commitA,otherRepository));
  await read(route());await read(route(fileA,commitA,otherRepository));
  assert.equal(source.calls.length,3);
  assert.equal(source.calls.filter(args=>args[0].includes(otherRepository)).length,2);
});

test('separate configured repositories have independent observations',async()=>{
  const source=countedRead(()=>content()),first=reader(source.read,true,repository),second=reader(source.read,true,otherRepository);
  await first(route());await second(route(fileA,commitA,otherRepository));
  await first(route());await second(route(fileA,commitA,otherRepository));
  assert.equal(source.calls.length,2);
});

test('disabled mode reads identical immutable route freshly every time',async()=>{
  const source=countedRead(()=>content()),read=reader(source.read,false);
  await read(route());await read(route());
  assert.equal(source.calls.length,2);
});

test('omitted enabled defaults to fresh reads',async()=>{
  const source=countedRead(()=>content());
  const read=createImmutableWorkflowSourceReader({read:source.read,repository});
  await read(route());await read(route());assert.equal(source.calls.length,2);
});

test('dynamic enablement is evaluated for every read and never bypassed on a hit',async()=>{
  let enabled=false;
  const source=countedRead((_api,index)=>content(fileA,`name: public dynamic ${index}\non: workflow_dispatch\n`));
  const read=reader(source.read,()=>enabled);
  const disabledFirst=await read(route()),disabledSecond=await read(route());
  assert.notEqual(disabledFirst.sha,disabledSecond.sha);
  enabled=true;
  const cached=await read(route());assert.deepEqual(await read(route()),cached);
  enabled=false;
  const newlyObserved=await read(route());assert.notEqual(newlyObserved.sha,cached.sha);
  enabled=true;
  assert.deepEqual(await read(route()),cached);
  assert.equal(source.calls.length,4,'disabled calls stay fresh even with an existing immutable cache entry');
});

const mutableRoutes=[
  '/repos/public-fixture/example/pulls/800',
  '/repos/public-fixture/example/branches/main',
  '/repos/public-fixture/example/actions/runs/42',
  '/repos/public-fixture/example/actions/runs/42/attempts/1',
  '/repos/public-fixture/example/actions/runs/42/attempts/1/jobs',
  '/repos/public-fixture/example/contents/.github/workflows?ref=main',
  '/repos/public-fixture/example/contents/.github/workflows/public-one.yml?ref=main',
  '/repos/public-fixture/example/contents/.github/workflows/public-one.yml?ref=feature/public',
];
for(const api of mutableRoutes)test(`mutable route retains fresh reads: ${api}`,async()=>{
  const source=countedRead((_api,index)=>({...content(),publicMetadata:{index}})),read=reader(source.read);
  const first=await read(api),second=await read(api);
  assert.equal(source.calls.length,2);assert.equal(first.publicMetadata.index,1);assert.equal(second.publicMetadata.index,2);
});

const nonExactSelectors=[
  route(fileA,'a'.repeat(39)),route(fileA,'a'.repeat(41)),route(fileA,'A'.repeat(40)),
  route(fileA,'a'.repeat(7)),route()+'&extra=1',route()+'#fragment',
  `/repos/${repository}/contents/${fileA}?x=1&ref=${commitA}`,
  `/repos/${repository}/contents/${fileA}?ref=${commitA}&ref=${commitB}`,
];
for(const api of nonExactSelectors)test(`non-exact immutable selector is never reused: ${api}`,async()=>{
  const source=countedRead(()=>content()),read=reader(source.read);
  await read(api);await read(api);assert.equal(source.calls.length,2);
});

const unsafePaths=['../public.yml','a/../public.yml','./public.yml','a/./public.yml','/public.yml',
  'a//public.yml','a/','a\\public.yml','a\u0000public.yml','a\u001fpublic.yml','a\u007fpublic.yml',
  'a\u0085public.yml','a\u2028public.yml','a\u2029public.yml','x'.repeat(4097)];
for(const [index,file] of unsafePaths.entries())test(`unsafe path never reuses content (${index+1})`,async()=>{
  const source=countedRead(()=>content(file)),read=reader(source.read);
  await read(route(file));await read(route(file));assert.equal(source.calls.length,2);
});

const rejectedContent=[
  ['null',()=>null],
  ['provider error object',()=>({message:'Not Found',status:404})],
  ['directory listing',()=>[content()]],
  ['non-file type',()=>({...content(),type:'dir'})],
  ['wrong path',()=>({...content(),path:fileB})],
  ['wrong git blob',()=>({...content(),sha:'c'.repeat(40)})],
  ['wrong encoding',()=>({...content(),encoding:'utf-8'})],
  ['content is not a string',()=>({...content(),content:null})],
  ['invalid base64 alphabet',()=>({...content(),content:'%not-base64%'})],
  ['declared size mismatch',()=>({...content(),size:content().size+1})],
  ['zero size',()=>({...content(),content:'',size:0,sha:blob(Buffer.alloc(0))})],
  ['fractional size',()=>({...content(),size:1.5})],
  ['unsafe integer size',()=>({...content(),size:Number.MAX_SAFE_INTEGER+1})],
  ['oversized content',()=>content(fileA,'x'.repeat(524289))],
  ['malformed UTF-8 with correct raw git blob',()=>{
    const bytes=Buffer.from([0xc3,0x28]);
    return {...content(),content:bytes.toString('base64'),size:bytes.length,sha:blob(bytes)};
  }],
];
for(const [label,produce] of rejectedContent)test(`invalid response never poisons cache: ${label}`,async()=>{
  const invalid=produce(),valid=content();
  const source=countedRead((_api,index)=>index<=2?invalid:valid),read=reader(source.read);
  assert.deepEqual(await read(route()),invalid);assert.deepEqual(await read(route()),invalid);
  assert.deepEqual(await read(route()),valid);assert.deepEqual(await read(route()),valid);
  assert.equal(source.calls.length,3,'both invalid observations remain fresh; later valid raw content can be reused');
});

test('provider throw is propagated and never cached',async()=>{
  const failure=Error('synthetic provider failure'),source=countedRead((_api,index)=>{
    if(index<=2)throw failure;return content();
  }),read=reader(source.read);
  await assert.rejects(read(route()),error=>error===failure);
  await assert.rejects(read(route()),error=>error===failure);
  await read(route());await read(route());assert.equal(source.calls.length,3);
});

test('first caller mutation cannot affect cached storage',async()=>{
  const expected=content(),source=countedRead(()=>structuredClone(expected)),read=reader(source.read);
  const first=await read(route());
  first.sha='d'.repeat(40);first.content='';first.publicMetadata.values.push('caller pollution');
  assert.deepEqual(await read(route()),expected);assert.equal(source.calls.length,1);
});

test('provider object mutation after fetch cannot affect cached storage',async()=>{
  const providerObject=content(),expected=structuredClone(providerObject),source=countedRead(()=>providerObject),read=reader(source.read);
  await read(route());providerObject.size=0;providerObject.publicMetadata.values.push('provider mutation');
  assert.deepEqual(await read(route()),expected);assert.equal(source.calls.length,1);
});

test('cached return mutation cannot affect subsequent cached returns',async()=>{
  const expected=content(),source=countedRead(()=>expected),read=reader(source.read);
  await read(route());const second=await read(route());
  second.path=fileB;second.publicMetadata.values.push('cached caller pollution');
  const third=await read(route());assert.deepEqual(third,expected);assert.notStrictEqual(third.publicMetadata,second.publicMetadata);
  assert.equal(source.calls.length,1);
});

test('64-entry ceiling preserves accepted entries and fetches overflow freshly',async()=>{
  const source=countedRead(api=>content(api.slice(api.indexOf('/contents/')+10,api.indexOf('?ref=')))),read=reader(source.read);
  const routes=Array.from({length:65},(_,index)=>route(`.github/workflows/public-${index}.yml`));
  for(const api of routes)await read(api);
  for(const api of routes)await read(api);
  assert.equal(source.calls.length,66);
  assert.equal(source.calls.filter(args=>args[0]===routes[0]).length,1);
  assert.equal(source.calls.filter(args=>args[0]===routes[63]).length,1);
  assert.equal(source.calls.filter(args=>args[0]===routes[64]).length,2);
});

test('invalid responses do not consume any of the 64 cache entries',async()=>{
  const validRoutes=Array.from({length:64},(_,index)=>route(`.github/workflows/public-valid-${index}.yml`));
  const invalidRoute=route('.github/workflows/public-invalid.yml');
  const source=countedRead(api=>api===invalidRoute?null:content(api.slice(api.indexOf('/contents/')+10,api.indexOf('?ref=')))),read=reader(source.read);
  await read(invalidRoute);await read(invalidRoute);
  for(const api of validRoutes)await read(api);
  for(const api of validRoutes)await read(api);
  assert.equal(source.calls.length,66);assert.equal(source.calls.filter(args=>args[0]===validRoutes[63]).length,1);
});

test('two observation factories never share cached content',async()=>{
  const source=countedRead((_api,index)=>content(fileA,`name: public observation ${index}\non: workflow_dispatch\n`));
  const first=reader(source.read),second=reader(source.read);
  const one=await first(route()),two=await second(route());
  assert.notEqual(one.sha,two.sha);
  assert.deepEqual(await first(route()),one);assert.deepEqual(await second(route()),two);
  assert.equal(source.calls.length,2);
});

test('fresh-reader delegate receives each uncacheable route without alteration',async()=>{
  const source=countedRead(api=>({observed:api})),read=reader(source.read);
  for(const api of mutableRoutes)assert.deepEqual(await read(api),{observed:api});
  assert.deepEqual(source.calls.map(args=>args[0]),mutableRoutes);
});


