const portableRepo='tdoljyj/cross-memory-system'; // API requires this public pair identity.
const portableTip='a'.repeat(40),portableHead='b'.repeat(40),portableOther='c'.repeat(40);
const portablePrNumber=800;
const portableSnapshotFiles=['scripts/ci/clued-gated-proof-profiles.json','scripts/ci/clued-gated-proof-role-specs.json',
  'scripts/ci/clued-work-admission.mjs','scripts/ci/clued-docs-only.py','scripts/ci/test_clued_docs_only.py',
  'config/merge-admission-policy.json'];
const portablePublisherFiles={publisherRegistry:'scripts/ci/clued-production-publisher-sources.json',
  publisherCompiler:'scripts/ci/clued-production-publisher-source.mjs',
  qualificationRegistry:'scripts/ci/clued-publisher-qualification-sources.json',
  qualificationCompiler:'scripts/ci/clued-publisher-qualification-source.mjs'};
const portableGraphTarget='.github/workflows/clued-handover-external-qualification.yml';
const portableNonCI=['.github/workflows/clued-merge-slot-ci.yml','.github/workflows/clued-work-admission-dispatch.yml'];

function portableActiveSource(index,inactive) {
  const trigger=inactive?{paths:['never-matching-fixture/**']}:null;
  const command=`echo public fixture ${index}`;
  const definition={name:`public active fixture ${index}`,on:{pull_request:trigger},jobs:{
    'admission-gate':{'runs-on':'ubuntu-latest',steps:[{name:'Public fixture gate',run:'echo fixture gate'}]},
    primary:{name:`public-primary-${index}`,'runs-on':'ubuntu-latest',steps:[{name:'Public fixture command',run:command}]}}};
  const text=`name: public active fixture ${index}\non:\n  pull_request:${inactive?'\n    paths:\n      - never-matching-fixture/**':''}\njobs:\n  admission-gate:\n    runs-on: ubuntu-latest\n    steps:\n      - name: Public fixture gate\n        run: echo fixture gate\n  primary:\n    name: public-primary-${index}\n    runs-on: ubuntu-latest\n    steps:\n      - name: Public fixture command\n        run: ${command}\n`;
  const role={job_id:'primary',definition_sha256:portableRoleDigest(definition.jobs.primary),definition:definition.jobs.primary};
  // This literal parser result is the synthetic fixture's complete definition;
  // the actual registration compiler, not a mirrored consumer, compiles it.
  const profile=portableCompile(text,{primary_ids:['primary'],parseYaml:()=>structuredClone(definition),accepted_roles:[role]});
  return {file:`.github/workflows/public-active-${String(index).padStart(2,'0')}.yml`,profile,roles:{sources:{[profile.workflow_blob]:[role]}}};
}

function portableWholeWorld() {
  const profiles={schema:'clued.gated-proof-profiles/2',workflows:structuredClone(portableFixedSources.floor_profiles),
    future_workflows:[],external2_future_workflows:structuredClone(portableFixedSources.pair_profiles)};
  const roleSpecs={schema:'clued.gated-proof-role-specs/2',workflows:structuredClone(portableFixedSources.floor_roles),
    future_workflows:[],external2_future_workflows:structuredClone(portableFixedSources.pair_roles)};
  for(let index=0;index<13;index++){
    const entry=portableActiveSource(index,index>=9);profiles.workflows[entry.file]=entry.profile;roleSpecs.workflows[entry.file]=entry.roles;
  }
  assert.equal(Object.keys(profiles.workflows).length,20);
  const bytes=new Map(),put=(ref,file,text)=>bytes.set(`${ref}:${file}`,Buffer.from(text,'utf8'));
  const defaultWorkflows=new Map(Object.entries(profiles.workflows).map(([file,profile])=>[file,profile.workflow_blob]));
  for(const [file,profile] of Object.entries(profiles.workflows))for(const ref of [portableTip,portableHead])put(ref,file,profile.source_yaml);
  for(const entry of profiles.external2_future_workflows)put(portableHead,entry.file,entry.source_profile.source_yaml);
  // Two changed existing non-CI workflows produce four immutable content keys.
  // Both retain an explicit non-PR dispatch boundary, never counted as tests.
  for(const [index,file] of portableNonCI.entries())for(const ref of [portableTip,portableHead])
    put(ref,file,`name: public non CI ${index}\non: workflow_dispatch\njobs:\n  notice:\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo public ${ref===portableTip?'before':'after'}\n`);
  const publisherSources={schema:'clued.production-publisher-sources/1',repository:portableRepo,default_branch:'main',workflows:{},roles:{}};
  const qualificationSources={schema:'clued.publisher-pr-qualification-sources/1',repository:portableRepo,default_branch:'main',workflows:{},roles:{}};
  const snapshotTexts={
    [portableSnapshotFiles[0]]:JSON.stringify(profiles),[portableSnapshotFiles[1]]:JSON.stringify(roleSpecs),
    ...Object.fromEntries(portableSnapshotFiles.slice(2).map(file=>[file,JSON.stringify({public_synthetic_fixture:true,authority:'NONE',file})])),
    [portablePublisherFiles.publisherRegistry]:JSON.stringify(publisherSources),
    [portablePublisherFiles.qualificationRegistry]:JSON.stringify(qualificationSources),
    [portablePublisherFiles.publisherCompiler]:'public synthetic publisher compiler',
    [portablePublisherFiles.qualificationCompiler]:'public synthetic qualification compiler'};
  for(const [file,text] of Object.entries(snapshotTexts))put(portableTip,file,text);
  const snapshot={tip:portableTip,checkout:portableTip,profiles,roleSpecs,publisherSources,qualificationSources,workflows:defaultWorkflows,
    files:Object.fromEntries(Object.entries(snapshotTexts).map(([file,text])=>[file,portableWorkflowBlob(text)]))};
  const content=(ref,file)=>{
    const raw=bytes.get(`${ref}:${file}`);assert.ok(raw,`unexpected public content fixture: ${file} at ${ref}`);
    return {type:'file',path:file,sha:portableWorkflowBlob(raw.toString('utf8')),encoding:'base64',size:raw.length,content:raw.toString('base64')};
  };
  const directory=ref=>[...bytes].filter(([key])=>key.startsWith(ref+':.github/workflows/'))
    .map(([key,raw])=>({type:'file',path:key.slice(41),sha:portableWorkflowBlob(raw.toString('utf8'))})).sort((a,b)=>a.path.localeCompare(b.path));
  const trees=new Map(),commits=new Map();
  for(const [index,ref] of [portableTip,portableHead].entries()){
    const treeIds=[0,1,2].map(part=>createHash('sha1').update(`public synthetic ${index} tree ${part}`).digest('hex'));
    commits.set(ref,{sha:ref,tree:{sha:treeIds[0]}});
    trees.set(treeIds[0],{sha:treeIds[0],truncated:false,tree:[{path:'.github',type:'tree',mode:'040000',sha:treeIds[1]}]});
    trees.set(treeIds[1],{sha:treeIds[1],truncated:false,tree:[{path:'workflows',type:'tree',mode:'040000',sha:treeIds[2]}]});
    trees.set(treeIds[2],{sha:treeIds[2],truncated:false,tree:directory(ref).map(row=>({path:row.path.split('/').at(-1),type:'blob',mode:'100644',sha:row.sha}))});
  }
  const changedFiles=[...profiles.external2_future_workflows.map(entry=>({filename:entry.file,status:'added'})),
    ...portableNonCI.map(filename=>({filename,status:'modified'})),{filename:portableSnapshotFiles[0],status:'modified'}];
  const pr={number:portablePrNumber,state:'open',draft:false,head:{sha:portableHead,repo:{full_name:portableRepo}},
    base:{sha:portableTip,ref:'main',repo:{full_name:portableRepo,default_branch:'main'}},changed_files:changedFiles.length,commits:1};
  const allSelected=[...Object.entries(profiles.workflows).filter(([_file,p])=>p.pull_request===null||!p.pull_request.paths[0].startsWith('never-')),
    ...profiles.external2_future_workflows.map(entry=>[entry.file,entry.source_profile])];
  assert.equal(allSelected.length,18);
  const runs=allSelected.map(([file,_profile],index)=>({id:1000+index,node_id:`PUBLIC_SOURCE_NODE_${index}`,path:file,
    run_attempt:index===0?2:1,head_sha:portableHead,event:'pull_request',status:'completed',conclusion:'success',
    pull_requests:[{number:portablePrNumber}],repository:{full_name:portableRepo},head_repository:{full_name:portableRepo}}));
  runs.push({id:2000,node_id:'PUBLIC_NONCOUNTED_NODE',path:portableNonCI[0],run_attempt:1,head_sha:portableHead,event:'pull_request',
    status:'completed',conclusion:'success',pull_requests:[{number:portablePrNumber}],repository:{full_name:portableRepo},head_repository:{full_name:portableRepo}});
  const jobs=new Map(runs.slice(0,18).map(run=>{
    const profile=allSelected.find(([file])=>file===run.path)[1],route=profile.routes[0],list=[];
    if(profile.gated)list.push({id:run.id*10,run_id:run.id,run_attempt:run.run_attempt,name:'admission-gate',status:'completed',conclusion:'success',steps:[]});
    list.push({id:run.id*10+1,run_id:run.id,run_attempt:run.run_attempt,name:route.name,
      labels:route.self_hosted?['self-hosted','linux']:['ubuntu-latest'],status:'completed',conclusion:'success',
      steps:Object.entries(route.required_steps).flatMap(([name,count])=>Array.from({length:count},()=>({name,status:'completed',conclusion:'success'})))});
    return [run.id,list];
  }));
  return {snapshot,content,directory,trees,commits,changedFiles,pr,runs,jobs};
}

async function runPortableWholeQualificationCase(name='positive',qualify=portableQualifyPrExecution) {
  const world=portableWholeWorld(),trace=[],occurrences=new Map(),graphs=new Map();
  const count=key=>{const n=(occurrences.get(key)??0)+1;occurrences.set(key,n);return n;};
  const result=await qualify({repository:portableRepo,head:portableHead,prNumber:portablePrNumber,
    snapshot:structuredClone(world.snapshot),
    read:async route=>{
      trace.push({kind:'REST_GET',route});const n=count(route);let value;
      if(route.endsWith(`/pulls/${portablePrNumber}`)){
        value=world.pr;if(name==='late-pr'&&n>2)value={...value,draft:true};
      }else if(route.includes('/compare/'))value={base_commit:{sha:portableTip},merge_base_commit:{sha:portableTip},total_commits:1,commits:[{sha:portableHead}],files:world.changedFiles};
      else if(route.endsWith('/branches/main'))value={commit:{sha:name==='late-main'&&n>1?portableOther:portableTip}};
      else if(route.includes('/contents/.github/workflows?')){
        const ref=route.split('ref=')[1];value=world.directory(ref);
        if(n>1&&((name==='late-default-directory'&&ref===portableTip)||(name==='late-head-directory'&&ref===portableHead)))value=[{...value[0],sha:'0'.repeat(40)},...value.slice(1)];
      }else if(route.includes('/contents/')){
        const [file,query]=route.split('/contents/')[1].split('?');value=world.content(query.slice(4),file);
        if(name==='late-trusted-raw'&&file===portableSnapshotFiles[0]&&n>1){
          const raw=Buffer.concat([Buffer.from(value.content,'base64'),Buffer.from('\n')]);value={...value,size:raw.length,content:raw.toString('base64')};
        }
      }else if(route.includes('/git/commits/'))value=world.commits.get(route.split('/git/commits/')[1]);
      else if(route.includes('/git/trees/'))value=world.trees.get(route.split('/git/trees/')[1]);
      else if(route.includes('/actions/runs?')){
        const rows=structuredClone(world.runs);
        if(name==='late-new-run'&&n>1)rows.push({...rows[0],id:3000,status:'queued',conclusion:null});
        value={total_count:rows.length,workflow_runs:rows};
      }else if(route.includes('/attempts/')){
        const id=Number(route.match(/runs\/(\d+)/)[1]);value={total_count:world.jobs.get(id).length,jobs:world.jobs.get(id)};
      }else if(/\/actions\/runs\/\d+$/.test(route)){
        value=world.runs.find(row=>route.endsWith('/'+row.id));
        if(name==='late-attempt')value={...value,run_attempt:value.run_attempt+1};
        if(name==='late-run-state')value={...value,status:'queued',conclusion:null};
      }else throw Error('unrequested public fixture route');
      assert.ok(value,`missing public fixture response: ${route}`);return structuredClone(value);
    },
    graphRead:async(query,variables)=>{
      if(query===PUBLISHER_SNAPSHOT_QUERY){
        trace.push({kind:'PUBLISHER_SNAPSHOT',variables});const n=count('publisher-snapshot');
        const [owner,repositoryName]=portableRepo.split('/');
        assert.deepEqual(variables,{owner,name:repositoryName,
          ...Object.fromEntries(Object.entries(portablePublisherFiles).map(([alias,file])=>[alias,`${portableTip}:${file}`]))});
        const repo={nameWithOwner:portableRepo};
        for(const [alias,file] of Object.entries(portablePublisherFiles)){
          const raw=world.content(portableTip,file);
          repo[alias]={__typename:'Blob',oid:raw.sha,byteSize:raw.size,text:Buffer.from(raw.content,'base64').toString('utf8'),isBinary:false,isTruncated:false};
          if(name===`late-${alias}`&&n>1)repo[alias].text+='\n';
        }
        return {data:{repository:repo}};
      }
      const {node}=variables;
      trace.push({kind:'GRAPH',node});const run=world.runs.find(row=>row.node_id===node);assert.ok(run);
      const n=(graphs.get(node)??0)+1;graphs.set(node,n);const late=n>1&&run.path===portableGraphTarget;
      const sourceCommit=late&&name==='late-source-commit'?portableOther:portableHead;
      const sourceRepository=late&&name==='late-source-repository'?'public-fixture/outside':portableRepo;
      return {data:{node:{databaseId:run.id,runAttempt:run.run_attempt,event:run.event,
        file:{path:run.path,repositoryName:sourceRepository,
          repositoryFileUrl:`https://github.com/${sourceRepository}/blob/${sourceCommit}/${run.path}`,
          run:{databaseId:run.id,runAttempt:run.run_attempt}}}}};
    },
    readLog:async()=>{trace.push({kind:'UNEXPECTED_LOG'});throw Error('synthetic Native membership is complete');}});
  return {authority:'NONE',case:name,result,callbacks:trace.length,trace,
    original_limits:{max_reads:160,observation_ms:90000,max_bytes:524288},actual_qualification:false,production_actions:0};
}

test('portable whole qualifyPrExecution finishes eighteen workflows and two fresh publisher snapshots in 159 callbacks',async()=>{
  const out=await runPortableWholeQualificationCase();
  assert.equal(out.result.passed,true,out.result.reason);assert.equal(out.result.state,'qualified');
  assert.equal(out.result.proofs.length,18);assert.equal(out.callbacks,159);
  const frequency=identity=>out.trace.filter(row=>row.route===identity).length;
  assert.equal(frequency(`/repos/${portableRepo}/pulls/${portablePrNumber}`),5);
  assert.equal(frequency(`/repos/${portableRepo}/branches/main`),3);
  for(const ref of [portableTip,portableHead]){
    assert.equal(frequency(`/repos/${portableRepo}/contents/.github/workflows?ref=${ref}`),2);
    assert.equal(frequency(`/repos/${portableRepo}/git/commits/${ref}`),2);
  }
  assert.equal(out.trace.filter(row=>row.kind==='GRAPH').length,36);
  assert.equal(out.trace.filter(row=>row.kind==='PUBLISHER_SNAPSHOT').length,2);
  assert.equal(out.trace.filter(row=>/\/actions\/runs\/\d+$/.test(row.route??'')).length,36);
  assert.equal(out.trace.filter(row=>row.route?.includes('/actions/runs?')).length,3);
  for(const file of [portableGraphTarget,'.github/workflows/clued-handover-disposable-idle.yml'])
    assert.equal(frequency(`/repos/${portableRepo}/contents/${file}?ref=${portableHead}`),1);
  for(const file of portableNonCI)for(const ref of [portableTip,portableHead])
    assert.equal(frequency(`/repos/${portableRepo}/contents/${file}?ref=${ref}`),1);
  for(const file of portableSnapshotFiles)assert.equal(frequency(`/repos/${portableRepo}/contents/${file}?ref=${portableTip}`),2);
  for(const file of Object.values(portablePublisherFiles))assert.equal(frequency(`/repos/${portableRepo}/contents/${file}?ref=${portableTip}`),0);
});

for(const name of ['late-pr','late-main','late-default-directory','late-head-directory','late-new-run',
  'late-attempt','late-run-state','late-source-commit','late-source-repository','late-trusted-raw',
  ...Object.keys(portablePublisherFiles).map(alias=>`late-${alias}`)])
  test(`portable whole qualifier rejects ${name} through its original fresh barrier`,async()=>{
    const out=await runPortableWholeQualificationCase(name);
    assert.equal(out.result.passed,false,out.result.reason);assert.ok(out.callbacks<=160);
    if(Object.keys(portablePublisherFiles).some(alias=>name===`late-${alias}`))
      assert.equal(out.trace.filter(row=>row.kind==='PUBLISHER_SNAPSHOT').length,2,'the final barrier was actually exercised');
  });
